class TestIntegration:
    """End-to-end validation scenarios."""

    def test_full_pipeline_roundtrip(self, tmp_path):
        """Generate matrix, serialize, deserialize, and verify integrity."""
        data = {
            "components": [
                {"name": f"svc_{i}", "path": f"services/svc_{i}"}
                for i in range(20)
            ]
        }
        file_path = tmp_path / "pipeline.json"
        file_path.write_text(json.dumps(data))

        result = generate_matrix(file_path)
        serialized = json.dumps(result)
        deserialized = json.loads(serialized)

        assert deserialized == result
        assert len(deserialized["include"]) == len(result["include"])

    def test_ci_workflow_compatibility(self, components_file):
        """Output should match GitHub Actions matrix format."""
        result = generate_matrix(components_file)
        # GitHub Actions expects: {"include": [{"key": "value"}, ...]}
        assert set(result.keys()) == {"include"}
        for entry in result["include"]:
            assert all(isinstance(v, str) for v in entry.values())

    def test_platform_config_matrix_completeness(self, tmp_path):
        """All platform/config combinations should be covered."""
        data = {
            "components": [{"name": "app", "path": "src/app"}],
            "platforms": ["linux", "macos", "windows"],
            "configs": ["debug", "release", "coverage"]
        }
        file_path = tmp_path / "full_matrix.json"
        file_path.write_text(json.dumps(data))

        result = generate_matrix(file_path)
        combos = {(e["platform"], e["config"]) for e in result["include"]}
        expected = {
            ("linux", "debug"), ("linux", "release"), ("linux", "coverage"),
            ("macos", "debug"), ("macos", "release"), ("macos", "coverage"),
            ("windows", "debug"), ("windows", "release"), ("windows", "coverage")
        }
        assert combos == expected


